using System.Text.Json;
using Scout.Core;

internal static class SearchUpgradeChecks
{
    internal static void Run(Action<string, Action> test)
    {
        var now = new DateTimeOffset(2026, 9, 24, 12, 0, 0, TimeSpan.Zero);
        var library = new Dictionary<string, LibraryItem>();
        Candidate File(string path, int age = 1) => new(path, ItemKind.File, Path.GetFileName(path), path)
        { Detail = Path.GetDirectoryName(path)!, ModifiedAt = now.AddMinutes(-age), CreatedAt = now.AddMinutes(-age) };
        void Check(bool value) { if (!value) throw new Exception("Search upgrade assertion failed"); }
        SearchResult Find(string query, params Candidate[] files) => SearchEngine.Search(query, Scope.All, files, library, now);
        foreach (var query in new[] { "show me the 3 newest files", "give me the newest three files", "could you find the three most recent files", "latest three files" })
            test("Count grammar: " + query, () => { var r = Find(query, Enumerable.Range(1, 8).Select(i => File(@"C:\Downloads\Item" + i + ".pdf", i)).ToArray()); Check(r.Intent.Count == 3 && r.Intent.Terms.Length == 0 && r.Hits.Count == 3 && r.Hits[0].Candidate.Title == "Item1.pdf" && RankingPolicy.Group(r).Length == 3); });
        test("Count syntax does not consume rolling time amounts", () => { var i = QueryParser.Parse("files opened in the last three hours", now); Check(i.Count == null && i.Window?.Since == now.AddHours(-3)); });
        test("Leading location clause retains request grammar", () => { var r = Find("""in "C:\Downloads", find the latest file""", File(@"C:\Downloads\a.md", 2), File(@"C:\Downloads\b.md")); Check(r.Hits[0].Candidate.Title == "b.md" && r.Intent.Terms.Length == 0); });
        test("Question punctuation is outside folder names", () => Check(Find("which file was changed most recently within Downloads?", File(@"C:\Downloads\a.md")).Hits.Count == 1));
        test("Desktop location does not make topics into folders", () => { Check(QueryParser.Parse("latest file on my desktop", now).Folder?.Text == "desktop"); Check(QueryParser.Parse("document on tax", now).Folder == null); });
        test("Quoted folder names protect type and date words", () => { var i = QueryParser.Parse("latest file in \"json yesterday\"", now); Check(i.Extension == null && i.Window == null && i.Folder?.Text == "json yesterday"); });
        test("Explicit folder survives earlier descriptive prepositions", () => { var r = Find("""document with notes from the team discussion in "C:\Meetings" """, File(@"C:\Meetings\Team minutes.docx"), File(@"C:\Elsewhere\Team minutes.docx")); Check(r.Intent.Folder?.Text == @"c:\meetings" && r.ModelShortlist.Count == 1 && r.ModelShortlist[0].Candidate.Detail == @"C:\Meetings" && LayaRanker.QueryFor(r.Intent).Contains("from the team discussion")); });
        test("Application mentioned in a PDF description preserves explicit location", () => { var r = Find("""pdf teaching me how to use the application in "C:\Guides" """, File(@"C:\Guides\User guide.pdf")); Check(r.Intent.Kind == ItemKind.File && r.Intent.Extension == ".pdf" && r.ModelShortlist.Count == 1); });
        test("File descriptions mentioning apps retain file intent without a folder", () => { foreach (var query in new[] { "pdf teaching me how to use the application", "markdown about the app structure", "document with instructions for the app" }) Check(QueryParser.Parse(query, now).Kind == ItemKind.File); foreach (var query in new[] { "pdf viewer", "pdf app", "app for reading pdfs", "open the text editor" }) Check(QueryParser.Parse(query, now).Kind == ItemKind.App); Check(QueryParser.Parse("pdf about the application", now, scope: Scope.Apps).Kind == ItemKind.App); });
        test("Document descriptions do not become media requests", () => { foreach (var query in new[] { "document recording what was discussed", "document about video production", "document explaining audio formats" }) { var i = QueryParser.Parse(query, now); Check(i.Kind == ItemKind.File && i.Extension == null); } Check(QueryParser.Parse("video recording of the meeting", now).Extension == "video"); Check(QueryParser.Parse("document mp4", now).Extension == ".mp4"); });
        test("Markdown recording choices is not a video or creation-date request", () => { var i = QueryParser.Parse("markdown recording the technical choices we made and their reasons", now); Check(i.Kind == ItemKind.File && i.Extension == ".md" && i.Recency == RecencyBasis.None); Check(QueryParser.Parse("presentations I made yesterday", now).Recency == RecencyBasis.Created); });
        test("Bare explicit types constrain metadata and disappear from terms", () => { foreach (var ext in new[] { "csv", "json", "yaml", "xml", "png", "zip" }) { var i = QueryParser.Parse(ext + " file", now); Check(i.Extension == "." + ext && i.Terms.Length == 0); } });
        test("Explicit type words remain searchable in app scope", () => { foreach (var name in new[] { "PDF Viewer", "JSON Editor", "ZIP Manager" }) Check(QueryParser.Parse(name, now, scope: Scope.Apps).Terms.Contains(name.Split(' ')[0].ToLowerInvariant())); });
        test("Partial filenames preserve underscores and hyphens", () => { foreach (var prefix in new[] { "demo_r", "camera-" }) { var expected = File(@"C:\Downloads\" + prefix + "eport.pdf", 5); var decoy = File(@"C:\Downloads\" + prefix.TrimEnd('-').Replace('_', ' ') + ".pdf"); Check(Find(prefix, decoy, expected).Hits[0].Candidate.Id == expected.Id); } });
        test("Camel case words retrieve files without losing literal names", () => { var f = File(@"C:\Downloads\ClientBillingReport.pdf"); Check(Find("billing report pdf", f).Hits.Count == 1 && Find(f.Title, f).Intent.Literal); });
        test("Exact filename tokens outrank unrelated body-only matches", () => { var named = File(@"C:\Reports\Quarterly quartzsignal notes.txt"); var body = File(@"C:\Reports\Unrelated notes.txt"); var catalog = new SearchCatalog([body, named]); var r = SearchEngine.Search("quartzsignal", Scope.Files, catalog, library, now, contentMatches: [new ContentMatch(body.Id, 180)]); var j = new RankResult(new Dictionary<string, double> { [named.Id] = .8 }, new HashSet<string>(), "test") { None = .1, Relevance = new Dictionary<string, double> { [named.Id] = .9 } }; Check(r.Hits[0].Candidate.Id == named.Id && r.Hits[0].Score > r.Hits[1].Score && RankingPolicy.Refine(r, j)[0].Candidate.Id == named.Id); });
        test("Model refinement cannot demote an unseen body-only match", () => { var body = File(@"C:\Reports\Unrelated notes.txt"); var semantic = File(@"C:\Reports\Customer overview.txt"); var catalog = new SearchCatalog([body, semantic]); var r = SearchEngine.Search("customer balance", Scope.Files, catalog, library, now, contentMatches: [new ContentMatch(body.Id, 180)]); var j = new RankResult(new Dictionary<string, double> { [semantic.Id] = .8 }, new HashSet<string>(), "test") { None = .1, Relevance = new Dictionary<string, double> { [semantic.Id] = .9 } }; Check(r.Hits.Single().Candidate.Id == body.Id && r.ModelShortlist.Single().Candidate.Id == semantic.Id && RankingPolicy.Refine(r, j)[0].Candidate.Id == body.Id); });
        test("Recency retains submillisecond and tick ordering", () => { var old = File(@"C:\Downloads\a.txt") with { ModifiedAt = now.AddTicks(-2) }; var latest = File(@"C:\Downloads\b.txt") with { ModifiedAt = now.AddTicks(-1) }; Check(Find("latest file", old, latest).Hits[0].Candidate.Id == latest.Id && Find("oldest file", latest, old).Hits[0].Candidate.Id == old.Id); });
        test("Model shortlist reserves broader candidates under lexical load", () => { var files = Enumerable.Range(0, 50).Select(i => File(@"C:\Reports\Quarterly report " + i + ".pdf")).Append(File(@"C:\Reports\Board update.pdf")).Append(File(@"C:\Elsewhere\Secret.pdf")).ToArray(); var r = Find("quarterly report pdf in Reports", files); Check(r.Hits.Count == 50 && r.ModelShortlist.Count == 32 && r.ModelShortlist.Any(h => h.Candidate.Title == "Board update.pdf") && r.ModelShortlist.All(h => h.Candidate.Detail == @"C:\Reports")); });
        test("Duplicate recall filenames leave room for distinct evidence", () => { var files = Enumerable.Range(0, 50).Select(i => File(@"C:\Reports\" + i + @"\Report.pdf")).Append(File(@"C:\Reports\Board update.pdf", 100)).ToArray(); var r = Find("pdf for leadership", files); Check(r.ModelShortlist.Any(h => h.Candidate.Title == "Board update.pdf") && r.ModelShortlist.Count == 32); });
        test("Resolved model query excludes enforced location and retains meaning", () => { var r = Find("""pdf for customer billing in "C:\Reports" """, File(@"C:\Reports\Invoice.pdf")); Check(LayaRanker.QueryFor(r.Intent) == "pdf for customer billing"); var unknown = Find("presentation from the meeting", File(@"C:\Reports\Board.pptx")); Check(LayaRanker.QueryFor(unknown.Intent).Contains("meeting")); });
        test("Independent relevance permits competing useful recall candidates", () => { var a = File(@"C:\Reports\Invoice one.pdf"); var b = File(@"C:\Reports\Invoice two.pdf"); var r = Find("pdf showing a customer balance", a, b); var j = new RankResult(new Dictionary<string, double> { [a.Id] = .46, [b.Id] = .44 }, new HashSet<string>(), "test") { None = .1, Relevance = new Dictionary<string, double> { [a.Id] = .95, [b.Id] = .93 } }; Check(RankingPolicy.Refine(r, j).Count == 2); Check(RankingPolicy.Refine(r, j with { Relevance = new Dictionary<string, double>() }).Count == 0); Check(RankingPolicy.Refine(r, j with { None = .6 }).Count == 0); });
        test("Relevance response rejects foreign IDs and invalid values", () => { var a = File(@"C:\Reports\Invoice.pdf"); foreach (var value in new[] { "{\"unknown\":0.9}", "{\"a\":1.1}", "[]" }) { using var body = JsonDocument.Parse("{\"scores\":{},\"relevance\":" + value + "}"); try { LayaRanker.Parse(body.RootElement, [a]); } catch (JsonException) { continue; } throw new Exception("Invalid relevance accepted"); } });
        test("Independent relevance never supersedes a stronger comparative choice", () => { var a = File(@"C:\Reports\Board update.pptx"); var b = File(@"C:\Reports\Company strategy.pptx"); var r = Find("presentation for leadership", a, b); var j = new RankResult(new Dictionary<string, double> { [a.Id] = .8, [b.Id] = .15 }, new HashSet<string>(), "test") { None = .05, Relevance = new Dictionary<string, double> { [a.Id] = .8, [b.Id] = .95 } }; Check(RankingPolicy.Refine(r, j)[0].Candidate.Id == a.Id); });
        test("Supported comparative winner retains influence with divided choice mass", () => { var a = File(@"C:\Reports\schema.json"); var b = File(@"C:\Reports\data.json"); var r = Find("json file defining the data structure", a, b); var j = new RankResult(new Dictionary<string, double> { [a.Id] = .35, [b.Id] = .3 }, new HashSet<string>(), "test") { None = .04, Relevance = new Dictionary<string, double> { [a.Id] = .93 } }; Check(RankingPolicy.Refine(r, j)[0].Candidate.Id == a.Id); Check(RankingPolicy.Refine(r with { Hits = [new(b, 1000)] }, j)[0].Candidate.Id == b.Id); });
        test("Common app roles preserve app aliases without explicit app noun", () => { var app = new Candidate("notepad", ItemKind.App, "Notepad", @"C:\Notepad.lnk") { Keywords = ["text editor"] }; Check(Find("open the text editor", app).Hits.Single().Candidate.Id == app.Id); Check(QueryParser.Parse("json file for the editor", now).Kind == ItemKind.File); });
        test("Depicted scenes stay descriptive unless a folder is explicit", () => { var r = Find("photo of snow in the mountains", File(@"C:\Pictures\Snow mountains.jpg")); Check(r.Intent.Folder == null && r.Intent.Terms.Contains("mountains")); Check(Find("photo of snow in absent folder", File(@"C:\Pictures\Snow mountains.jpg")).ModelShortlist.Count == 0); });
    }
}
